import"./chunk-VC46IEJQ.js";var e=(t,o,s,r,l,i,a,n)=>({name:{en:t[0],zh:t[1]},desc:{en:o[0],zh:o[1]},tour:{en:s[0],zh:s[1]},source:{confidence:r,refs:l,book:{en:i[0],zh:i[1]},unknown:{en:a[0],zh:a[1]},interpretation:{en:n[0],zh:n[1]}}}),h=["The books give no description of this.","\u4E66\u4E2D\u5BF9\u6B64\u5E76\u65E0\u63CF\u5199\u3002"],d={id:"lorath",intro:{en:"The most remote of the Free Cities, set on the largest of three islands in the cold Shivering Sea off northern Essos. The novels barely describe it; this scene is a quiet, atmospheric reading of grey stone, sheltered water and fog.",zh:"\u6D1B\u62C9\u65AF\u662F\u6700\u504F\u8FDC\u7684\u81EA\u7531\u8D38\u6613\u57CE\u90A6\uFF0C\u4F4D\u4E8E\u5384\u7D22\u65AF\u5317\u5CB8\u5916\u5BD2\u51B7\u7684\u98A4\u6296\u6D77\u4E2D\uFF0C\u5EFA\u5728\u4E09\u5EA7\u5C9B\u5C7F\u91CC\u6700\u5927\u7684\u4E00\u5EA7\u4E0A\u3002\u5C0F\u8BF4\u5BF9\u5B83\u51E0\u65E0\u7740\u58A8\uFF1B\u672C\u573A\u666F\u4EE5\u7070\u77F3\u3001\u907F\u98CE\u6C34\u6E7E\u4E0E\u6D53\u96FE\uFF0C\u8425\u9020\u4E00\u4EFD\u9759\u8C27\u7684\u6C1B\u56F4\u3002"},notes:{en:"Established (thinly): an island city on the largest of three islands, at the mouth of Lorath Bay on the Shivering Sea, remote from the other Free Cities. Companion lore (not shown) tells of ancient stone mazes left by the Mazemakers and of the vanished cult of Boash. Invented: the lagoon, quays, towers, halls, the entire plan and every building form.",zh:"\u53EF\u786E\u8BA4\u7684\u4E0D\u591A\uFF1A\u57CE\u5E02\u5EFA\u5728\u98A4\u6296\u6D77\u6D1B\u62C9\u65AF\u6E7E\u53E3\u4E09\u5C9B\u4E2D\u6700\u5927\u7684\u4E00\u5EA7\u4E0A\uFF0C\u4E0E\u5176\u4F59\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u76F8\u8DDD\u9065\u8FDC\u3002\u8BBE\u5B9A\u96C6\u8FD8\u8BB0\u8F7D\u4E86\u4E0A\u53E4\u201C\u8FF7\u5BAB\u5EFA\u9020\u8005\u201D\u7559\u4E0B\u7684\u77F3\u780C\u8FF7\u5BAB\uFF0C\u4EE5\u53CA\u5DF2\u7ECF\u6D88\u4EA1\u7684\u6CE2\u963F\u4EC0\u6559\u6D3E\uFF08\u672C\u573A\u666F\u5747\u672A\u5448\u73B0\uFF09\u3002\u81EA\u62DF\u90E8\u5206\uFF1A\u6F5F\u6E56\u3001\u7801\u5934\u3001\u5854\u697C\u3001\u5385\u5802\u3001\u6574\u4F53\u5E03\u5C40\u4E0E\u6240\u6709\u5EFA\u7B51\u9020\u578B\u3002"},tour:["shivering-sea","three-islands","lagoon-harbour","city-quarter","grey-towers","stone-halls"],sources:[{ref:"acok",checked:"memory",note:{en:"A prisoner in the novels names Lorath as his home; this is about all the novels say of the city. Recalled, not re-read.",zh:"\u5C0F\u8BF4\u4E2D\u4E00\u540D\u56DA\u72AF\u81EA\u79F0\u6765\u81EA\u6D1B\u62C9\u65AF\uFF0C\u8FD9\u51E0\u4E4E\u5C31\u662F\u5C0F\u8BF4\u5BF9\u8BE5\u57CE\u7684\u5168\u90E8\u4EA4\u4EE3\u3002\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"City on the largest of three islands in the Shivering Sea, at the mouth of Lorath Bay; the Mazemakers and Boash: confirmed by web-search summaries, pages not fetched.",zh:"\u57CE\u5E02\u4F4D\u4E8E\u98A4\u6296\u6D77\u4E09\u5C9B\u4E2D\u6700\u5927\u4E00\u5C9B\u3001\u6D1B\u62C9\u65AF\u6E7E\u53E3\uFF1B\u8FF7\u5BAB\u5EFA\u9020\u8005\u4E0E\u6CE2\u963F\u4EC0\u6559\u6D3E\uFF1A\u7ECF\u7F51\u7EDC\u641C\u7D22\u6458\u8981\u5370\u8BC1\uFF0C\u672A\u80FD\u6253\u5F00\u9875\u9762\u3002"}},{ref:"twoiaf",checked:"not-accessed",note:{en:"Lorathi history and customs not re-checked against the book.",zh:"\u6D1B\u62C9\u65AF\u7684\u5386\u53F2\u4E0E\u98CE\u4FD7\u672A\u5BF9\u7167\u539F\u4E66\u6838\u5B9E\u3002"}}],landmarks:{"shivering-sea":e(["Shivering Sea","\u98A4\u6296\u6D77"],["Cold grey water and mist surround the islands; fishing boats keep close to shore.","\u51B0\u51B7\u7684\u7070\u8272\u6D77\u6C34\u4E0E\u96FE\u6C14\u73AF\u7ED5\u7FA4\u5C9B\uFF0C\u6E14\u8239\u4E0D\u6562\u8FDC\u79BB\u6D77\u5CB8\u3002"],["Cold water and fog keep Lorath apart from the other Free Cities.","\u51B7\u6D77\u4E0E\u6D53\u96FE\uFF0C\u628A\u6D1B\u62C9\u65AF\u548C\u5176\u4F59\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u9694\u5F00\u3002"],"medium",["maps","awoiaf"],["Lorath lies in the Shivering Sea, north of the other Free Cities.","\u6D1B\u62C9\u65AF\u4F4D\u4E8E\u98A4\u6296\u6D77\u4E2D\uFF0C\u5728\u5176\u4F59\u81EA\u7531\u8D38\u6613\u57CE\u90A6\u4EE5\u5317\u3002"],["Sea conditions and shipping.","\u6D77\u51B5\u4E0E\u822A\u8FD0\u3002"],["A choppy grey sea with a few fishing boats; invented.","\u5FAE\u6D6A\u8D77\u4F0F\u7684\u7070\u8272\u6D77\u9762\u4E0E\u51E0\u6761\u6E14\u8239\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"three-islands":e(["Three Islands","\u4E09\u5C9B"],["A cluster of three islands, with the city on the largest; the two smaller isles fade into the mist.","\u4E09\u5C9B\u76F8\u805A\uFF0C\u57CE\u5E02\u5728\u6700\u5927\u7684\u4E00\u5EA7\u4E0A\uFF0C\u4E24\u5EA7\u5C0F\u5C9B\u9690\u6CA1\u5728\u96FE\u4E2D\u3002"],["Three islands, only one of them home to a city.","\u4E09\u5EA7\u5C9B\u5C7F\uFF0C\u552F\u6709\u4E00\u5EA7\u5EFA\u8D77\u4E86\u57CE\u5E02\u3002"],"medium",["awoiaf"],["The city stands on the largest of three islands.","\u57CE\u5E02\u4F4D\u4E8E\u4E09\u5C9B\u4E2D\u6700\u5927\u7684\u4E00\u5EA7\u3002"],["The size and shape of the islands.","\u5404\u5C9B\u7684\u5927\u5C0F\u4E0E\u5F62\u72B6\u3002"],["Rough oval islands with low hills; invented.","\u8D77\u4F0F\u4F4E\u7F13\u7684\u692D\u5706\u5F62\u5C9B\u5C7F\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"lagoon-harbour":e(["Lagoon Harbour","\u6F5F\u6E56\u6E2F"],["A sheltered lagoon on the island's west side, with small boats and stone quays.","\u5C9B\u897F\u4FA7\u7684\u907F\u98CE\u6F5F\u6E56\uFF0C\u6CCA\u7740\u5C0F\u8239\uFF0C\u77F3\u780C\u7801\u5934\u73AF\u7ED5\u3002"],["Sheltered water inside the island, with mist on the surface.","\u5C9B\u5185\u4E00\u6E7E\u907F\u98CE\u9759\u6C34\uFF0C\u96FE\u6C14\u6D6E\u5728\u6C34\u9762\u3002"],"low",["awoiaf"],["An island port city is implied; no harbour is described.","\u53EF\u63A8\u77E5\u8FD9\u662F\u4E00\u5EA7\u5C9B\u4E0A\u6E2F\u57CE\uFF0C\u4F46\u5E76\u65E0\u6E2F\u53E3\u63CF\u5199\u3002"],["The harbour's real form.","\u6E2F\u53E3\u7684\u771F\u5B9E\u5F62\u6001\u3002"],["An oval lagoon with a channel to the sea; invented.","\u4E00\u6E7E\u692D\u5706\u6F5F\u6E56\uFF0C\u6709\u6C34\u9053\u901A\u5411\u5916\u6D77\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"city-quarter":e(["City Quarter","\u57CE\u533A"],["Tight grey houses with slate roofs ring the lagoon, smoke rising into the damp air.","\u77F3\u677F\u9876\u7684\u7070\u8272\u623F\u5C4B\u7D27\u7D27\u56F4\u7740\u6F5F\u6E56\uFF0C\u708A\u70DF\u5347\u5165\u6E7F\u51B7\u7684\u7A7A\u6C14\u3002"],["Houses crowd the water, quiet and grey.","\u623F\u5C4B\u6324\u5728\u6C34\u8FB9\uFF0C\u7070\u6697\u800C\u5B89\u9759\u3002"],"low",["awoiaf"],h,["Streets, districts and architecture.","\u8857\u9053\u3001\u57CE\u533A\u4E0E\u5EFA\u7B51\u3002"],["Generic compact housing; invented.","\u4E00\u822C\u6027\u7684\u5BC6\u96C6\u6C11\u5C45\uFF1B\u7CFB\u81EA\u62DF\u3002"]),"grey-towers":e(["Grey Towers","\u7070\u5854"],["A handful of slim stone towers rise above the roofs and the mist.","\u51E0\u5EA7\u7EC6\u957F\u7684\u77F3\u5854\u9AD8\u51FA\u5C4B\u9876\uFF0C\u63A2\u51FA\u96FE\u5916\u3002"],["Towers stand above the fog, whether for watch or for show.","\u9AD8\u5854\u7ACB\u4E8E\u96FE\u4E0A\uFF0C\u6216\u4E3A\u77AD\u671B\uFF0C\u6216\u4E3A\u88C5\u70B9\u3002"],"low",["awoiaf"],h,["Whether any such towers exist.","\u662F\u5426\u771F\u6709\u8FD9\u6837\u7684\u5854\u3002"],["Five towers; purely invented.","\u4E94\u5EA7\u5854\uFF1B\u7EAF\u5C5E\u81EA\u62DF\u3002"]),"stone-halls":e(["Stone Halls","\u77F3\u5385"],["Plain, quiet halls on the high ground by the lagoon, in keeping with a remote and withdrawn city.","\u6F5F\u6E56\u65C1\u9AD8\u5730\u4E0A\u51E0\u5EA7\u6734\u7D20\u5B89\u9759\u7684\u77F3\u5385\uFF0C\u4E0E\u8FD9\u5EA7\u504F\u8FDC\u5B64\u50FB\u7684\u57CE\u90A6\u76F8\u79F0\u3002"],["Plain, quiet buildings for a city far from everywhere.","\u6734\u7D20\u5B89\u9759\u7684\u5EFA\u7B51\uFF0C\u5C5E\u4E8E\u4E00\u5EA7\u8FDC\u79BB\u5C18\u56A3\u7684\u57CE\u3002"],"low",["twoiaf"],["Lorath is described as the most remote of the Free Cities; no building is described.","\u6D1B\u62C9\u65AF\u88AB\u79F0\u4E3A\u6700\u504F\u8FDC\u7684\u81EA\u7531\u8D38\u6613\u57CE\u90A6\uFF1B\u4F46\u6CA1\u6709\u4EFB\u4F55\u5EFA\u7B51\u63CF\u5199\u3002"],["Any specific institution or building, including the Mazemakers' mazes.","\u4EFB\u4F55\u5177\u4F53\u7684\u673A\u6784\u6216\u5EFA\u7B51\uFF0C\u5305\u62EC\u8FF7\u5BAB\u5EFA\u9020\u8005\u7684\u8FF7\u5BAB\u3002"],["One long hall and two outbuildings; invented, with no religious claim made.","\u4E00\u5EA7\u957F\u5385\u4E0E\u4E24\u95F4\u9644\u5C4B\uFF1B\u7CFB\u81EA\u62DF\uFF0C\u4E0D\u6D89\u53CA\u4EFB\u4F55\u5B97\u6559\u542B\u4E49\u3002"])}};export{d as default};
